import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { breadcrumbItemStyles } from './page-header.styles.js';

/**
 * A breadcrumb item. The last item automatically gets `aria-current="page"`.
 *
 * @element bl-breadcrumb-item
 * @slot - Link or text content.
 */
@customElement('bl-breadcrumb-item')
export class BlBreadcrumbItem extends LitElement {
  static override styles = [tokens, breadcrumbItemStyles];

  /** Whether this is the current page. Set automatically by bl-breadcrumb. */
  @property({ type: Boolean, reflect: true })
  current = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'listitem');
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('current')) {
      if (this.current) {
        this.setAttribute('aria-current', 'page');
      } else {
        this.removeAttribute('aria-current');
      }
    }
  }

  protected override render() {
    return html`<slot></slot>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-breadcrumb-item': BlBreadcrumbItem;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { breadcrumbStyles } from './page-header.styles.js';

/**
 * Breadcrumb navigation following WAI-ARIA Breadcrumb pattern.
 * Visual separators via CSS `::before` (not in DOM).
 *
 * @element bl-breadcrumb
 * @slot - `bl-breadcrumb-item` elements.
 */
@customElement('bl-breadcrumb')
export class BlBreadcrumb extends LitElement {
  static override styles = [tokens, breadcrumbStyles];

  /** Accessible label for the navigation. */
  @property()
  label = 'Breadcrumb';

  private _handleSlotChange(): void {
    const items = this.querySelectorAll('bl-breadcrumb-item');
    // Mark the last item as current
    items.forEach((item, i) => {
      if (i === items.length - 1) {
        item.setAttribute('current', '');
      } else {
        item.removeAttribute('current');
      }
    });
  }

  protected override render() {
    return html`
      <nav aria-label=${this.label}>
        <ol part="list">
          <slot @slotchange=${this._handleSlotChange}></slot>
        </ol>
      </nav>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-breadcrumb': BlBreadcrumb;
  }
}

export { BlPageHeader } from './page-header.js';
export { BlBreadcrumb } from './breadcrumb.js';
export { BlBreadcrumbItem } from './breadcrumb-item.js';

import { css } from 'lit';

export const pageHeaderStyles = css`
  :host {
    display: block;
    font-family: var(--bl-font-family-base);
  }

  .page-header {
    display: flex;
    flex-direction: column;
    gap: var(--bl-spacing-md);
    padding-bottom: var(--bl-spacing-lg);
    border-bottom: 1px solid var(--bl-color-neutral-200);
  }

  .breadcrumb-area {
    display: contents;
  }

  .breadcrumb-area ::slotted(*) {
    margin-bottom: var(--bl-spacing-xs);
  }

  .header-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--bl-spacing-lg);
  }

  .header-content {
    flex: 1;
    min-width: 0;
  }

  .title ::slotted(*) {
    margin: 0;
    font-size: var(--bl-font-size-xl);
    font-weight: 600;
    color: var(--bl-color-neutral-900);
    line-height: 1.3;
  }

  .description {
    margin-top: var(--bl-spacing-xs);
  }

  .description ::slotted(*) {
    margin: 0;
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-500);
    line-height: 1.5;
  }

  .actions {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-sm);
    flex-shrink: 0;
  }
`;

export const breadcrumbStyles = css`
  :host {
    display: block;
    font-family: var(--bl-font-family-base);
  }

  nav {
    display: block;
  }

  ol {
    display: flex;
    align-items: center;
    list-style: none;
    margin: 0;
    padding: 0;
    gap: var(--bl-spacing-xs);
    flex-wrap: wrap;
  }
`;

export const breadcrumbItemStyles = css`
  :host {
    display: inline-flex;
    align-items: center;
    font-size: var(--bl-font-size-sm);
    font-family: var(--bl-font-family-base);
  }

  :host(:not(:first-child))::before {
    content: '/';
    color: var(--bl-color-neutral-400);
    margin-right: var(--bl-spacing-xs);
  }

  a,
  ::slotted(a) {
    color: var(--bl-color-neutral-500);
    text-decoration: none;
    transition: color var(--bl-transition-fast);
  }

  a:hover,
  ::slotted(a:hover) {
    color: var(--bl-color-primary-600);
  }

  :host([current]) ::slotted(*),
  :host([current]) span {
    color: var(--bl-color-neutral-900);
    font-weight: 500;
  }

  ::slotted(*):focus-visible,
  a:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: 2px;
    border-radius: var(--bl-radius-xs);
  }
`;

import { LitElement, html } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { pageHeaderStyles } from './page-header.styles.js';

/**
 * Page header with title, description, and actions layout via named slots.
 *
 * @element bl-page-header
 * @slot breadcrumb - Breadcrumb navigation above the title.
 * @slot - Title content (typically an h1).
 * @slot description - Subtitle/description text.
 * @slot actions - Action buttons/links.
 */
@customElement('bl-page-header')
export class BlPageHeader extends LitElement {
  static override styles = [tokens, pageHeaderStyles];

  protected override render() {
    return html`
      <div class="page-header" part="base">
        <div class="breadcrumb-area">
          <slot name="breadcrumb"></slot>
        </div>
        <div class="header-row">
          <div class="header-content">
            <div class="title" part="title">
              <slot></slot>
            </div>
            <div class="description" part="description">
              <slot name="description"></slot>
            </div>
          </div>
          <div class="actions" part="actions">
            <slot name="actions"></slot>
          </div>
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-page-header': BlPageHeader;
  }
}
